"""Official ChatGPT-plan OAuth and Responses transport; no API-key fallback.

Credentials belong to this local installation, never to negotiation memory.
See docs/CHATGPT_SIGN_IN.md for the public OpenAI integration contract.
"""

import fcntl
import json
import math
import os
import re
import tempfile
import time
import uuid
from contextlib import contextmanager
from pathlib import Path
from urllib.parse import urlsplit

import httpx
import jwt

ISSUER = "https://auth.openai.com"
RESOURCE = "https://api.openai.com/v1"
SCOPE = "openid profile email offline_access resource.invoke chatgpt.tokens.use.direct"
PLAN_SCOPES = {"resource.invoke", "chatgpt.tokens.use.direct"}
AUTH_DIR = Path(__file__).resolve().parents[2] / ".chatgpt-auth"


class PlanAccessError(RuntimeError):
    """Safe identifiers only: callers may log this exception."""

    def __init__(self, code="chatgpt_authentication_required"):
        self.code = code if re.fullmatch(r"[a-z_\.]{1,100}", str(code)) else "chatgpt_access_failed"
        super().__init__(self.code)


def auth_mode():
    mode = os.environ.get("OPENAI_AUTH_MODE", "api_key")
    if mode not in {"api_key", "chatgpt"}:
        raise ValueError("OPENAI_AUTH_MODE must be api_key or chatgpt")
    return mode


def safe_error(error, default="chatgpt_access_failed"):
    error = error if isinstance(error, dict) else {}
    return PlanAccessError(error.get("code") or error.get("type") or default)


def checked_json(response):
    try:
        body = response.json()
    except ValueError:
        raise PlanAccessError("chatgpt_invalid_response") from None
    if not isinstance(body, dict):
        raise PlanAccessError("chatgpt_invalid_response")
    if response.is_error:
        error = body.get("error")
        if isinstance(error, str):
            error = {"code": error}
        raise safe_error(error)
    return body


def atomic_json(path, value):
    fd, tmp = tempfile.mkstemp(prefix=".pending-", dir=path.parent)
    try:
        with os.fdopen(fd, "w") as f:
            json.dump(value, f)
            f.write("\n")
            f.flush()
            os.fsync(f.fileno())
        os.chmod(tmp, 0o600)
        os.replace(tmp, path)
    finally:
        if os.path.exists(tmp):
            os.unlink(tmp)


@contextmanager
def locked_store(timeout=10):
    AUTH_DIR.mkdir(mode=0o700, exist_ok=True)
    os.chmod(AUTH_DIR, 0o700)
    lock = AUTH_DIR / "credentials.lock"
    fd = os.open(lock, os.O_CREAT | os.O_RDWR, 0o600)
    with os.fdopen(fd, "a") as handle:
        end = time.monotonic() + timeout
        while True:
            try:
                fcntl.flock(handle, fcntl.LOCK_EX | fcntl.LOCK_NB)
                break
            except BlockingIOError:
                if time.monotonic() >= end:
                    raise PlanAccessError("chatgpt_credentials_busy") from None
                time.sleep(0.05)
        try:
            path = AUTH_DIR / "credentials.json"
            if path.exists():
                data = json.loads(path.read_text())
            else:
                data = {"host_id": "urn:uuid:" + str(uuid.uuid4()), "profiles": {}, "active": None}
                atomic_json(path, data)
            yield data
        finally:
            fcntl.flock(handle, fcntl.LOCK_UN)


def save_store(data):
    atomic_json(AUTH_DIR / "credentials.json", data)


def discovery(client):
    config = checked_json(client.get(ISSUER + "/.well-known/openid-configuration"))
    if config.get("issuer") != ISSUER:
        raise PlanAccessError("chatgpt_invalid_issuer")
    for field in ("authorization_endpoint", "token_endpoint", "jwks_uri", "revocation_endpoint"):
        url = urlsplit(config.get(field, ""))
        if url.scheme != "https" or url.netloc != "auth.openai.com" or url.username or url.fragment:
            raise PlanAccessError("chatgpt_invalid_discovery")
    return config


def validate_identity(client, config, raw_token, client_id, nonce=None, subject=None):
    try:
        header = jwt.get_unverified_header(raw_token)
        # Never derive accepted algorithms from an untrusted token.
        if header.get("alg") != "RS256" or not header.get("kid"):
            raise ValueError("unsupported signing key")
        keys = checked_json(client.get(config["jwks_uri"]))["keys"]
        jwk = next(k for k in keys if k.get("kid") == header["kid"] and k.get("kty") == "RSA")
        claims = jwt.decode(raw_token, jwt.PyJWK.from_dict(jwk).key, algorithms=["RS256"],
                            audience=client_id, issuer=ISSUER,
                            options={"require": ["exp", "iat", "iss", "aud", "sub"]})
        if not isinstance(claims["sub"], str) or not claims["sub"]:
            raise ValueError("missing identity")
        if nonce is not None and claims.get("nonce") != nonce:
            raise ValueError("nonce mismatch")
        if subject is not None and claims["sub"] != subject:
            raise ValueError("account changed")
        if claims.get("azp", client_id) != client_id:
            raise ValueError("authorized party mismatch")
        if isinstance(claims["aud"], list) and len(claims["aud"]) > 1 and claims.get("azp") != client_id:
            raise ValueError("missing authorized party")
        return claims
    except (jwt.PyJWTError, ValueError, KeyError, StopIteration, TypeError):
        raise PlanAccessError("chatgpt_identity_validation_failed") from None


def token_record(token, previous=None):
    previous = previous or {}
    access = token.get("access_token")
    lifetime = token.get("expires_in")
    if (not isinstance(access, str) or not access or token.get("token_type", "").lower() != "bearer"
            or not isinstance(lifetime, (int, float)) or not math.isfinite(lifetime) or lifetime <= 0):
        raise PlanAccessError("chatgpt_invalid_token_response")
    scope = token.get("scope")
    scopes = scope.split() if isinstance(scope, str) else previous.get("scopes", [])
    return {**previous, "access_token": access, "refresh_token": token.get("refresh_token")
            or previous.get("refresh_token"), "id_token": token.get("id_token") or previous.get("id_token"),
            "scopes": scopes, "expires_at": time.time() + lifetime, "token_type": "Bearer"}


class ChatGPTConnection:
    def __init__(self, profile_id=None):
        with locked_store() as data:
            self.profile_id = profile_id or data["active"]
            if self.profile_id not in data["profiles"]:
                raise PlanAccessError()

    def access_token(self, timeout=15):
        # The profile is pinned for this router; changing the active account cannot
        # change who pays midway through an Arena session. Refresh rotation is locked.
        with locked_store(timeout=timeout) as data:
            profile = data["profiles"].get(self.profile_id, {})
            if not PLAN_SCOPES <= set(profile.get("scopes", [])) or not profile.get("access_token"):
                raise PlanAccessError("chatgpt_plan_permission_required")
            if profile.get("expires_at", 0) > time.time() + 60:
                return profile["access_token"]
            if not profile.get("refresh_token"):
                raise PlanAccessError()
            with httpx.Client(timeout=timeout, follow_redirects=False) as client:
                config = discovery(client)
                token = checked_json(client.post(config["token_endpoint"], data={
                    "grant_type": "refresh_token", "client_id": profile["client_id"],
                    "refresh_token": profile["refresh_token"], "resource": RESOURCE,
                }))
                renewed = token_record(token, profile)
                if token.get("id_token"):
                    validate_identity(client, config, token["id_token"], profile["client_id"],
                                      subject=profile["subject"])
                data["profiles"][self.profile_id] = renewed
                save_store(data)
                if not PLAN_SCOPES <= set(renewed["scopes"]):
                    raise PlanAccessError("chatgpt_plan_permission_required")
                return renewed["access_token"]

    def models(self):
        with httpx.Client(timeout=15, follow_redirects=False) as client:
            result = checked_json(client.get(RESOURCE + "/models", headers={
                "Authorization": "Bearer " + self.access_token(),
            }))
        models = result.get("models")
        if not isinstance(models, list):
            raise PlanAccessError("chatgpt_invalid_model_catalog")
        return [m for m in models if isinstance(m, dict) and m.get("visibility") == "list"]

    def require_model(self, model):
        if model not in {m.get("slug") for m in self.models()}:
            raise PlanAccessError("chatgpt_requested_model_unavailable")


def stream_response(client, connection, payload, timeout, record):
    """Return only a completed response. Partial output never authorizes a move."""
    end = time.monotonic() + timeout
    token = connection.access_token(timeout=max(1, min(timeout / 2, 10)))
    remaining = end - time.monotonic()
    if remaining <= 0:
        raise TimeoutError("ChatGPT response budget exhausted")
    body = dict(payload)
    body.pop("max_output_tokens", None)  # Unsupported on the ChatGPT-plan route.
    body["input"] = [{"role": "user", "content": [{"type": "input_text", "text": payload["input"]}]}]
    body.update(store=False, stream=True)
    with client.stream("POST", RESOURCE + "/responses", headers={"Authorization": "Bearer " + token},
                       json=body, timeout=remaining) as response:
        record["http_status"] = response.status_code
        if response.is_error:
            response.read()
            checked_json(response)
        if "text/event-stream" not in response.headers.get("content-type", ""):
            raise PlanAccessError("chatgpt_invalid_stream")
        fields, size = [], 0
        for line in response.iter_lines():
            if time.monotonic() >= end:
                raise TimeoutError("ChatGPT response budget exhausted")
            size += len(line)
            if size > 4_000_000:
                raise PlanAccessError("chatgpt_response_too_large")
            if line.startswith("data:"):
                fields.append(line[5:].lstrip(" "))
            elif not line and fields:
                raw, fields = "\n".join(fields), []
                if raw == "[DONE]":
                    break
                event = json.loads(raw)
                kind = event.get("type")
                if kind == "response.completed":
                    result = event.get("response", {})
                    if result.get("status") != "completed":
                        raise PlanAccessError("chatgpt_incomplete_response")
                    return result
                if kind == "response.failed":
                    raise safe_error(event.get("response", {}).get("error"))
                if kind == "error":
                    raise safe_error(event.get("error", event))
                if kind == "response.incomplete":
                    raise PlanAccessError("chatgpt_incomplete_response")
        raise PlanAccessError("chatgpt_stream_interrupted")
